async function mapLimit(items, limit, fn) {
    if (limit <= 0) {
        throw new Error('Limit must be positive');
    }

    const results = [];
    const pending = [];
    const resolvePending = (index) => {
        if (index < results.length) {
            pending.shift().then((result) => {
                results[index] = result;
                if (pending.length) {
                    resolvePending(index + 1);
                }
            }).catch((error) => {
                throw error;
            });
        }
    };

    for (let i = 0; i < items.length; i++) {
        const promise = Promise.resolve(fn(items[i]));
        if (pending.length < limit) {
            promise.then((result) => {
                results.push(result);
                resolvePending(i + 1);
            }).catch((error) => {
                throw error;
            });
        } else {
            pending.push(promise);
        }
    }

    while (pending.length) {
        const promise = pending.shift();
        promise.then((result) => {
            results.push(result);
        }).catch((error) => {
            throw error;
        });
    }

    return results;
}
