def parse_int_list(text):
    fields = [field.strip() for field in text.split(',')]
    int_list = []
    for i, field in enumerate(fields, start=1):
        if field == '':
            raise ValueError(f"Empty element at field {i}")
        try:
            int_list.append(int(field))
        except ValueError:
            raise ValueError(f"Invalid token '{field}' at field {i}")
    return int_list
